def transform(g):
    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    colors={}
    for r in range(H):
        for c in range(W):
            if g[r][c]: colors.setdefault(g[r][c],[]).append((r,c))
    # bar colors: all cells in a single column, contiguous
    barcols={}
    for v,cells in colors.items():
        cs={c for _,c in cells}
        if len(cs)==1:
            rs=sorted(r for r,_ in cells)
            if rs==list(range(rs[0],rs[0]+len(rs))):
                barcols[v]=(rs[0],cs.pop(),len(rs))
    # order bar colors top to bottom
    seq=[v for v,(r,c,h) in sorted(barcols.items())]
    barh={v:barcols[v][2] for v in seq}
    # remove bar
    for v,(r0,c,h) in barcols.items():
        for r in range(r0,r0+h): g[r][c]=0
    # remaining shape cells
    rem={}
    for r in range(H):
        for c in range(W):
            if g[r][c]: rem.setdefault(g[r][c],[]).append((r,c))
    order=sorted(rem, key=lambda v: min(r for r,_ in rem[v]))
    bottom=order[-1]
    r0=min(r for r,_ in rem[bottom]); c0=min(c for _,c in rem[bottom])
    pat=[(r-r0,c-c0) for r,c in rem[bottom]]
    h=max(r for r,_ in pat)+1
    top=min(r for r,_ in rem[order[0]])
    add=[v for v in seq if v not in rem]
    n=len(add)
    for i,v in enumerate(add):  # i=0 is topmost added
        base=top-h*(n-i)
        for dr,dc in pat: g[base+dr][c0+dc]=v
    return g
