    bottom=order[-1]
    r0=min(r for r,_ in rem[bottom]); c0=min(c for _,c in rem[bottom])
    pat=[(r-r0,c-c0) for r,c in rem[bottom]]
    h=max(r for r,_ in pat)+1
    top=min(r for r,_ in rem[order[0]])
    k=seq.index(order[0])  # position of existing topmost shape color in bar sequence
    for i,v in enumerate(seq):
        if v in rem: continue
        base=top-h*(k-i)
        for dr,dc in pat: g[base+dr][c0+dc]=v
    return g
